scripts.鸨母对话.txt:
// 与鸨母的对话

	CheckYear($Value);  
	If ($Value == 0) @NotYuanDan;	
	If ($Value == 1) @YuanDan;	
	
@NotYuanDan:

	If ($Event == 307) @Event307;
	If ($Event == 360) @Event360;

	GetRandNum($Talkbaomu051,0,1);
	If ($Talkbaomu051 == 0) @Talk0;
	If ($Talkbaomu051 == 1) @Talk1;
	
@Talk0:
	Say("鸨母：公子，楼上有个从外国来的洋姑娘，公子要不要去尝尝鲜啊！", 87);
	Return;

@Talk1:	
	Say("鸨母：公子，我们春花秋月楼个个都是美女，最近又来了一个江南佳丽，不过她此刻不在。", 87);
	Return;	
   
